+	if err := r.cleanupPersistedTestGroupObjects(ctx, validationRequestName); err != nil {
+		slog.WarnContext(ctx, "Failed to clean up finished TestGroup objects", "validationRequest",
+			validationRequestName, "error", err)
+	}
